import { AUTOMODE } from "../texts.ts";
import { isObject } from "./merge.ts";
import type { Change, Json } from "./types.ts";

/** The entry that makes a list of `autoMode` take the built-in list of Claude Code. */
export const DEFAULTS = "$defaults";

const show = (v: unknown) => (v === undefined ? "(unset)" : JSON.stringify(v));

/**
 * `had` with `DEFAULTS` first, and each entry of `want` that it lacks added at the end.
 * The entries of `had` stay, and no entry comes twice.
 */
export const listWith = (had: unknown[], want: unknown[]): unknown[] => [
  DEFAULTS,
  ...had.filter((v) => v !== DEFAULTS),
  ...want.filter((v) => v !== DEFAULTS && !had.includes(v)),
];

/**
 * `current` with the `autoMode` lists of `AUTOMODE` merged in, and one change line for each list that differs.
 * A value of `autoMode` that is not an object gets its own change line, and the lists start again from `AUTOMODE`.
 */
export const planAutoMode = (current: unknown, changes: Change[]): Json => {
  const root: Json = isObject(current) ? current : {};
  const existing = root["autoMode"];
  const base: Json = isObject(existing) ? existing : {};
  if (existing !== undefined && !isObject(existing))
    changes.push({
      key: "autoMode",
      line: `autoMode: ${show(existing)} -> (an object)`,
    });
  const out: Json = { ...base };
  for (const [key, want] of Object.entries(AUTOMODE as Json)) {
    const had = Array.isArray(base[key]) ? base[key] : [];
    const next = listWith(had, want as unknown[]);
    if (JSON.stringify(base[key]) !== JSON.stringify(next))
      changes.push({
        key: `autoMode.${key}`,
        line: `autoMode.${key}: ${show(base[key])} -> ${show(next)}`,
      });
    out[key] = next;
  }
  return { ...root, autoMode: out };
};
